# Load packages required to define the pipeline:
library(targets)

# `tar_make_future()` only runs target branches concurrently when a parallel
# future plan is declared in this script. Candidate models already use four
# parallel chains internally, so four model workers means at most 16 active
# chains. Reduction-only stages also use the same four-worker schedule.
protein_model_workers <- suppressWarnings(as.integer(
  Sys.getenv("PROTEIN_MODEL_WORKERS", unset = "4")
))
if (
  length(protein_model_workers) != 1L ||
    is.na(protein_model_workers) ||
    protein_model_workers < 1L
) {
  stop("PROTEIN_MODEL_WORKERS must be a positive integer.", call. = FALSE)
}
future::plan(
  future::multisession,
  workers = protein_model_workers
)

# Set target options:
tar_option_set(packages = c("here",
                            "qs",
                            "tidyverse",
                            "metafor",
                            "mgcv",
                            "patchwork",
                            "splines",
                            "lspline",
                            "rstan",
                            "brms",
                            "loo",
                            "bayestestR",
                            "tidybayes",
                            "marginaleffects",
                            "grateful"),
               seed = 1988,  # <-- GLOBAL reproducible seed
               memory = "transient",
               format = "qs",
               garbage_collection = TRUE,
               storage = "worker",
               retrieval = "worker"
               ) 

# Run the R scripts in the R/ folder with your custom functions:
tar_source("R/functions.R")
tar_source("R/incremental_update.R")
tar_source("R/primary_model_diagnostics.R")
tar_source("R/primary_model_loo.R")
tar_source("R/primary_model_averaging.R")
tar_source("R/sensitivity_pilots.R")
tar_source("R/sensitivity_rescor_full.R")
tar_source("R/sensitivity_strategy.R")
tar_source("R/update_2026_sensitivity.R")
tar_source("R/update_2026_absolute_exposures.R")
tar_source("R/publication_bias.R")
tar_source("R/publication_bias_models.R")
tar_source("R/grade.R")
tar_source("R/software_report.R")
tar_source("R/verification_artifacts.R")
tar_source("R/preprint_reporting.R")

tar_source("R/measurement_sensitivity.R")

tar_source("R/measurement_targets.R")

# Freeze completed opt-in fits whenever their family is disabled. Without this
# cue, changing the environment switch back to "none" can replace an expensive
# cached fit with the lightweight `not_run` sentinel returned by the fit helper.
sensitivity_pilot_runtime_flags <- parse_sensitivity_pilot_selection(
  Sys.getenv("PROTEIN_SENSITIVITY_PILOTS", unset = "none")
)

# The updated primary refit is intentionally opt-in because it launches 104
# full four-chain models. Successful file-backed fits remain frozen when the
# switch is later disabled.
update_2026_primary_runtime_enabled <- tolower(
  Sys.getenv("PROTEIN_UPDATE_2026_PRIMARY", unset = "false")
) %in% c("1", "true", "yes", "fit")

# Updated-primary remedies use a separate switch so running a remedy can never
# reactivate or invalidate the completed 104-model initial fitting stage.
update_2026_primary_remedy_runtime_enabled <- tolower(
  Sys.getenv("PROTEIN_UPDATE_2026_PRIMARY_REMEDY", unset = "false")
) %in% c("1", "true", "yes", "fit")

# Integrated PSIS-LOO is also opt-in. It opens each large accepted fit only in
# its own branch and writes a compact durable reduction to the model archive.
update_2026_primary_loo_runtime_enabled <- tolower(
  Sys.getenv("PROTEIN_UPDATE_2026_PRIMARY_LOO", unset = "false")
) %in% c("1", "true", "yes", "run")

# Exact case-deletion refits are separately enabled after the integrated PSIS
